def find_objs(g):
    # maximal uniform-filled rectangles, including interior colors, any size
    h,w=len(g),len(g[0])
    seen=set(); objs=[]
    for r in range(h):
        for c in range(w):
            col=g[r][c]
            if col==0 or (r,c) in seen: continue
            st=[(r,c)]; cells=set()
            while st:
                a,b=st.pop()
                if (a,b) in cells: continue
                cells.add((a,b))
                for da,db in [(1,0),(-1,0),(0,1),(0,-1)]:
                    na,nb=a+da,b+db
                    if 0<=na<h and 0<=nb<w and g[na][nb]==col and (na,nb) not in cells: st.append((na,nb))
            rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
            r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
            if all(g[rr][cc]==col for rr in range(r0,r1+1) for cc in range(c0,c1+1)):
                for p in cells: seen.add(p)
                objs.append({'color':col,'r0':r0,'c0':c0,'r1':r1,'c1':c1})
    return objs

def solve(g):
    objs=find_objs(g)
    # containment edges: A contains B if B inside A span strictly
    n=len(objs)
    anc={i:[] for i in range(n)}
    for i in range(n):
        for j in range(n):
            if i==j: continue
            if (objs[j]['r0']>=objs[i]['r0'] and objs[j]['r1']<=objs[i]['r1']
                and objs[j]['c0']>=objs[i]['c0'] and objs[j]['c1']<=objs[i]['c1']):
                anc[i].append(j)
    depth={}
    changed=True
    while changed:
        changed=False
        for i in range(n):
            if i in depth: continue
            ds=[depth[j]+1 for j in anc[i]]
            if ds:
                depth[i]=max(ds)
                changed=True
    dmax=max(depth.values())
    out=[row[:] for row in g]
    for o in objs:
        i=objs.index(o)
        d=depth.get(i,0)
        if d<dmax:
            target_d=dmax-d
            cand=[j for j in range(n) if depth.get(j,0)==target_d]
            if cand:
                o2=objs[cand[0]]
                for rr in range(o['r0'],o['r1']+1):
                    for cc in range(o['c0'],o['c1']+1):
                        if g[rr][cc]==o['color']: out[rr][cc]=o2['color']
    return out

