def peel(g):
    # repeatedly take the largest uniform rectangle whose boundary is all one color
    # and interior is not all that color
    H,W=len(g),len(g[0]); out=[row[:] for row in g]; rem=[row[:] for row in g]
    res=[]
    changed=True
    while changed:
        changed=False
        best=None
        for r in range(H):
            for c in range(W):
                col=rem[r][c]
                if col==0: continue
                for hh in range(1,H-r+1):
                    for ww in range(1,W-c+1):
                        sub=[[rem[r+i][c+j] for j in range(ww)] for i in range(hh)]
                        # boundary all col, interior not all col (or solid small?) treat solid only if no larger ring
                        boundary=all(sub[i][0]==sub[i][-1]==col for i in range(hh)) and all(sub[0][j]==sub[-1][j]==col for j in range(ww))
                        if not boundary: continue
                        interior=all(v==col for row in sub for v in row)
                        if interior and hh<3 or not interior:
                            area=hh*ww
                            if best is None or area>best[0]: best=(area,col,r,c,hh,ww)
        if best is None: break
        area,col,r,c,hh,ww=best; changed=True
        res.append((col,r,c,hh,ww))
        for i in range(hh):
            for j in range(ww):
                rem[r+i][c+j]=0
    return res,res

