def layers(g,bg=0):
    # find maximal solid-colored rectangles (rings may touch) via greedy: repeatedly extract largest solid rect
    H,W=len(g),len(g[0]); remaining=[[1]*W for _ in range(H)]; rects=[]
    while True:
        best=None
        for r in range(H):
            for c in range(W):
                if not remaining[r][c]: continue
                # max square/rect anchored at (r,c) extending while solid
                h=w=1
                while r+h<H and remaining[r+h][c] and g[r+h][c]==g[r][c]: h+=1
                while c+w<W and remaining[r][c+w] and g[r][c+w]==g[r][c]: w+=1
                if best is None or (h*w,h+w)>best[0]: best=(h,w,h+r,r+c,g[r][c])
        if best is None: break
        rects.append(best[4]); remaining=[row[:] for row in remaining]
        r,c=best[2],best[3]; h,w=best[0],best[1]
        for i in range(r,min(r+h,H)):
            for j in range(c,min(c+w,W)): remaining[i][j]=False
    return rects
