            res.append((col,min(rs),max(rs),min(cs),max(cs)))
    return res
def solve_chain(rects,bg=0):
    # containment tree
    def inside(a,b):  # a inside b
        return a[1]>=b[1] and a[2]<=b[2] and a[3]>=b[3] and a[4]<=b[4]
    n=len(rects)
    parent=[None]*n
    for i in range(n):
        for j in range(n):
            if i!=j and inside(rects[i],rects[j]):
                parent[i]=j; break
    roots=[i for i in range(n) if parent[i] is None]
    o=[list(r) for r in rects]  # [col,r1,r2,c1,c2]
    for root in roots:
        # collect path from root down
        path=[]; cur=root
        while cur is not None:
            path.append(cur); cur=parent[cur]
        path.reverse()
        newcol=[o[i][0] for i in path][::-1]
        for k,(rr,_,_,cc,_) in enumerate(path):
            o[rr][0]=newcol[len(path)-1-k]
    return o
